                "category": "pdbx_contact_author",
                "title": "ORCID",
                "type": "text",
                "required": true,
                "conditions": [],
                "help": "The Open Researcher and Contributor ID (ORCID).",
                "placeholder": "e.g. 0000-0002-6681-547X"
